<script>
$(function () {
    $('#dailyProductivityEntryModal').on('show.bs.modal', function (event) {
        var button = $(event.relatedTarget);
        var modal = $(this);
        ['date', 'source', 'title', 'category', 'minutes', 'status', 'description', 'staff'].forEach(function (field) {
            modal.find('[data-entry-field="' + field + '"]').text(button.attr('data-' + field) || '');
        });
    });
    $('#dailyProductivityEntryEditModal').on('show.bs.modal', function (event) {
        var button = $(event.relatedTarget);
        var modal = $(this);
        modal.find('form').attr('action', button.attr('data-edit-url'));
        modal.find('#edit_entry_date').val(button.attr('data-entry-date'));
        modal.find('#edit_title').val(button.attr('data-title'));
        modal.find('#edit_minutes_spent').val(button.attr('data-minutes'));
        modal.find('#edit_entry_category').selectpicker('val', button.attr('data-category'));
        modal.find('#edit_description').val(button.attr('data-description'));
    });
});
</script>
